const PRETTY = {"ghl":"GoHighLevel","hubspot":"HubSpot","shopify":"Shopify","stripe":"Stripe","quickbooks":"QuickBooks","zapier":"Zapier","twilio":"Twilio","pipedrive":"Pipedrive","monday":"Monday.com","activecampaign":"ActiveCampaign","n8n":"n8n","xero":"Xero","salesforce":"Salesforce","airtable":"Airtable","make":"Make","zoho":"Zoho","klaviyo":"Klaviyo","netsuite":"NetSuite","clickup":"ClickUp","instantly":"Instantly.ai","close":"Close","notion":"Notion"};

